import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_P(x, y, z):
    try:
        # Calculate y^x
        if y == 0:
            if x > 0:
                y_x = 0
            elif x == 0:
                y_x = 1  # Standard convention
            else: # x < 0
                return None # 0 raised to negative power is undefined
        else:
            y_x = y ** x

        # Calculate z^y
        if z == 0:
            if y > 0:
                z_y = 0
            elif y == 0:
                z_y = 1  # Standard convention
            else: # y < 0
                return None # 0 raised to negative power is undefined
        else:
            z_y = z ** y

        # Calculate x^z
        if x == 0:
            if z > 0:
                x_z = 0
            elif z == 0:
                x_z = 1  # Standard convention
            else: # z < 0
                return None # 0 raised to negative power is undefined
        else:
            x_z = x ** z

        # P = y^x * z^y * x^z
        P = y_x * z_y * x_z

        # P must be an integer (which it should be if intermediate steps worked) and positive
        if isinstance(P, float):
            return None # Should not happen with integer inputs, but safety check

        return P

    except OverflowError:
        return None # Result too large to handle
    except Exception:
        # Catch other potential domain errors
        return None

def find_good_triples():
    good_triples = []
    search_range = range(-4, 5)

    for x in search_range:
        for y in search_range:
            for z in search_range:
                P = calculate_P(x, y, z)

                if P is not None and P > 0 and is_prime(P):
                    S = x**2 + y**2 + z**2
                    good_triples.append({'triple': (x, y, z), 'S': S})

    # Sort according to the rule: x_k^2 + y_k^2 + z_k^2 <= x_{k+1}^2 + y_{k+1}^2 + z_{k+1}^2
    good_triples.sort(key=lambda item: item['S'])

    return good_triples

results = find_good_triples()

# Output the results in a structured way
print("--- Found Good Triples ---")
for i, item in enumerate(results):
    print(f"k={i+1}: Triple {item['triple']}, Sum of Squares S = {item['S']}")

# Check how many triples were found
print(f"\nTotal good triples found: {len(results)}")

# Check the 200th triple existence (though unlikely to reach it with this small range)
if len(results) >= 200:
    x200, y200, z200 = results[199]['triple']
    S200 = results[199]['S']
    print(f"\nRequired value for k=200: S = {S200}")
else:
    print("\nNot enough good triples found in the search range |x|,|y|,|z| <= 4.")

